# ── Dignity relationship ───────────────────────────────────────────────────────
def dignity(graha_key, rashi_name, gd):
    if rashi_name == gd["exalt"]:    return ("exalted",   "в экзальтации")
    if rashi_name == gd["debil"]:    return ("debilitated","в падении")
    if rashi_name in gd["own"]:      return ("own sign",  "в собственном знаке")
    rashi_ruler = next(r[2] for r in RASHIS if r[0] == rashi_name)
    if rashi_ruler in gd["friends"]: return ("friendly",  "в дружественном знаке")
    if rashi_ruler in gd["enemies"]: return ("inimical",  "во враждебном знаке")
    return ("neutral", "в нейтральном знаке")

