# ── Build rules ────────────────────────────────────────────────────────────────
ORDINALS = {1:'1st',2:'2nd',3:'3rd',4:'4th',5:'5th',6:'6th',
            7:'7th',8:'8th',9:'9th',10:'10th',11:'11th',12:'12th'}

rules = []
for graha_key, gd in GRAHAS.items():
    for i, rdata in enumerate(RASHIS, 1):
        rashi, rashi_ru, ruler, element, mode, rashi_en, rashi_ru_desc = rdata
        dignity_en, dignity_ru = dignity(graha_key, rashi, gd)

        rid = f'vedic-rule.graha-rashi.{graha_key.lower()}-in-{rashi.lower()}'
        interp = INTERP.get((graha_key, rashi))

        if interp:
            s_en, s_ru, p_en, p_ru, g_en, g_ru = interp
        else:
            s_en = f'{graha_key} in {rashi}: {gd["principle_en"]} meets the field of {rashi_en}.'
            s_ru = f'{gd["ru"]} в {rashi_ru}: {gd["principle_ru"]} встречается с полем {rashi_ru_desc}.'
            p_en = f'The {dignity_en} placement shapes how this combination expresses in the chart.'
            p_ru = f'Положение {dignity_ru} формирует, как эта комбинация выражается в карте.'
            g_en = f'Consciously integrate the principle of {gd["principle_en"]} within the field of {rashi_en}.'
            g_ru = f'Осознанно интегрировать принцип {gd["principle_ru"]} в поле {rashi_ru_desc}.'

        rule = {
            'id': rid,
            'system': 'vedic',
            'methodFamily': 'psychological-vedic',
            'factor': {'graha': graha_key, 'rashi': rashi},
            'dignity': {'status': dignity_en, 'statusRu': dignity_ru},
            'sourceIds': ['source.narasimha-rao-vedic-integrated', 'source.agarwal-vedic-v2'],
            'themes': [graha_key.lower(), rashi.lower(), element, mode, dignity_en.split()[0]],
            'themesRu': [gd['ru'], rashi_ru, element, dignity_ru.split()[0]],
            'simple': {
                'summary': s_en,
                'pattern': p_en,
                'growth': g_en,
                'reflection': f'How does the quality of {rashi_en} shape how you express {gd["principle_en"]}?',
            },
            'simpleRu': {
                'summary': s_ru,
                'pattern': p_ru,
                'growth': g_ru,
                'reflection': f'Как качество {rashi_ru_desc} формирует то, как вы выражаете {gd["principle_ru"]}?',
            },
            'advanced': {
                'technical': f'{graha_key} in {rashi}: {dignity_en}. Rashi lord: {ruler}. Element: {element}, mode: {mode}.',
                'method': 'Vedic graha-in-rashi: the graha principle expresses through the symbolic field of the rashi. Dignity (exaltation/debilitation/own sign/friendly/inimical) modifies the quality and ease of expression.',
                'caution': 'Graha-in-rashi is one factor among many. Aspects (drishti), house placement (bhava), nakshatra, and dasha period all modify the expression significantly.',
                'constructiveChannel': f'Channel the principle of {gd["principle_en"]} through the constructive qualities of {rashi_en}: {rashi_en}.',
            },
            'advancedRu': {
                'technical': f'{gd["ru"]} в {rashi_ru}: {dignity_ru}. Господин раши: {GRAHAS.get(ruler, {}).get("ru", ruler)}. Стихия: {element}, модус: {mode}.',
                'method': 'Ведическая граха-в-раши: принцип грахи выражается через символическое поле раши. Достоинство (экзальтация/падение/своя обитель/дружественный/враждебный знак) изменяет качество и лёгкость выражения.',
                'caution': 'Граха-в-раши — один фактор среди многих. Аспекты (дришти), положение в бхаве, накшатра и период дашы существенно изменяют выражение.',
                'constructiveChannel': f'Направить принцип {gd["principle_ru"]} через конструктивные качества {rashi_ru}: {rashi_ru_desc}.',
            },
            'confidence': 'medium',
        }
        rules.append(rule)

print(f'Generated {len(rules)} vedic rashi rules')
json.dump(rules, open(OUT_FILE, 'w', encoding='utf-8'), ensure_ascii=False, indent=2)
print('Saved', OUT_FILE)

# Add knowledge graph nodes
new_nodes = []
for r in rules:
    if r['id'] not in existing_nodes:
        g = r['factor']['graha']
        rs = r['factor']['rashi']
        new_nodes.append(json.dumps({
            'id': r['id'], 'type': 'rule',
            'label': f'{GRAHAS[g]["ru"]} в {next(rd[1] for rd in RASHIS if rd[0]==rs)}',
            'system': 'vedic', 'status': 'draft'
        }, ensure_ascii=False) + '\n')

with open(NODES_FILE, 'a', encoding='utf-8') as f:
    f.writelines(new_nodes)
print(f'Added {len(new_nodes)} nodes')
print('Done.')
